887	    }
888	
889	    lv_draw_buf_init(b, 240, 320, LV_COLOR_FORMAT_RGB565, stride, px,
890	                     stride * 320u);
891	    s_push_buf[i] = b;
892	    s_push_psram[i] = px;
893	    syslog(LOG_WARNING, "[vperf] ui push buf%d: PSRAM 兜底 %p\n", i, px);
