6745	/** @brief 表盘页整页刷值（500 ms UI 节拍）。 */
6746	static void helm_dial_tick(const bicycle_runtime_t * rt)
6747	{
6748	    const bool paused = s_sh.paused;
6749	    const uint32_t ink = paused ? HELM_COLOR_TRACK : HELM_COLOR_INK;
6750	    float speed = rt ? rt->speed_kph : 0.0f;
6751	    char buf[32];
6752	    int v10;
6753	    int i;
6754	
6755	    if (speed < 0.0f) {
6756	        speed = 0.0f;
6757	    }
6758	    if (speed > 60.0f) {
6759	        speed = 60.0f;
6760	    }
6761	    v10 = (int)(speed * 10.0f + 0.5f);
6762	
6763	    if (s_sh.dial_arc != NULL) {
6764	        lv_arc_set_value(s_sh.dial_arc, (v10 + 5) / 10);
6765	    }
6766	    helm_fmt_speed(buf, sizeof(buf), speed);
6767	    helm_label_set(s_sh.dial_speed, buf);
6768	    helm_set_text_hex(s_sh.dial_speed, ink);
6769	    helm_set_text_hex(s_sh.dial_unit, HELM_COLOR_MUTE);
6770	    if (s_sh.dial_spd_ptr != NULL) {
6771	        int x = HELM_SPD_BAR_X +
6772	                (int)(((int32_t)HELM_SPD_BAR_W * v10 + 300) / 600) - 1;
6773	
6774	        if (x < HELM_SPD_BAR_X + 1) {
6775	            x = HELM_SPD_BAR_X + 1;
6776	        }
6777	        if (x > HELM_SPD_BAR_X + HELM_SPD_BAR_W - 4) {
6778	            x = HELM_SPD_BAR_X + HELM_SPD_BAR_W - 4;
6779	        }
6780	        lv_obj_set_x(s_sh.dial_spd_ptr, x);
6781	    }
6782	
6783	    /* 心率：值 + 紧跟的单位 + 右侧「均 / 峰」；无有效心率整行退到 "--"，
6784	     * 指针/描边收起（不自造 0 bpm）。 */
6785	    if (rt != NULL && rt->hr_valid && rt->hr_bpm > 0u) {
6786	        lv_point_t sz;
6787	        int bpm = (int)rt->hr_bpm;
6788	        int z = helm_dial_hr_zone(bpm);
6789	        int bx0 = HELM_HR_BAR_X + (z - 1) * HELM_HR_BAR_W / 5;
6790	        int bx1 = HELM_HR_BAR_X + z * HELM_HR_BAR_W / 5;
6791	
6792	        lv_snprintf(buf, sizeof(buf), "%d", bpm);
6793	        helm_label_set(s_sh.dial_hr_val, buf);
6794	        lv_txt_get_size(&sz, buf, s_sh.font_val, 0, 0, LV_COORD_MAX,
6795	                        LV_TEXT_FLAG_NONE);
6796	        if (s_sh.dial_hr_unit != NULL) {
6797	            lv_obj_set_x(s_sh.dial_hr_unit, HELM_HR_BAR_X + sz.x + 4);
6798	        }
6799	        if (s_sh.dial_hr_sel != NULL) {
6800	            lv_obj_set_pos(s_sh.dial_hr_sel, bx0, HELM_HR_BAR_Y);
6801	            lv_obj_set_size(s_sh.dial_hr_sel, bx1 - bx0, HELM_HR_BAR_H);
6802	            lv_obj_set_style_border_color(s_sh.dial_hr_sel,
6803	                helm_color(s_dial_hr_deep[z - 1]), 0);
6804	            lv_obj_remove_flag(s_sh.dial_hr_sel, LV_OBJ_FLAG_HIDDEN);
6805	        }
