/* ── 演示/取证：骑行页三态（仅模拟器脚本调用，板端不接）─────────────────
 * 页面数据仍只读 `bicycle_runtime_get()`；这里负责把运行时推到指定状态：
 *   · 里程/时长：`bicycle_runtime_seed_session()`（公开 API）；
 *   · 心率/踏频/功率/海拔/坡度：`bicycle_runtime_update_sensors/env()`；
 *   · 时速：运行时没有"静止也能给出指定速度"的写入口（数值由 GNSS 位移
 *     窗口反推），取证时直接写 `speed_kph` 字段并每拍重放。这是**测试脚手架**，
 *     不参与任何业务逻辑；板端不会走到（只有模拟器 tour 脚本调这三个入口）。
 *   · 自动暂停关掉：速度 0 的取证图要停在手动状态，不能被 4 s 自动暂停改灰。
 */
static float s_demo_speed_kph = -1.0f;
static bool s_demo_ride_seeded;

/** @brief 每拍把注入的时速/传感器重放到 runtime（正常固件永不触发）。 */
static void helm_demo_runtime_apply(void)
{
    bicycle_runtime_t * drt;

    if (s_demo_speed_kph < 0.0f) {
        return;
    }
    drt = (bicycle_runtime_t *)(uintptr_t)bicycle_runtime_get();
    if (drt != NULL) {
        drt->speed_kph = s_demo_speed_kph;
        /* 海拔/坡度：GNSS 桩每拍会把 altitude 重写掉，取证值在这里重放。 */
        drt->has_altitude = true;
        drt->altitude_m = 326.0f;
        drt->grade_pct = 2.4f;
        drt->hr_avg_bpm = 148u;
        drt->hr_max_bpm = 151u;
    }
    bicycle_runtime_update_sensors(148, true, 84, true, 220, true);
}

void helm_shell_demo_ride(float speed_kph)
{
    bicycle_runtime_t * drt;

    if (!s_sh.attached) {
        printf("helm: demo ride ignored (not attached)\n");
        return;
    }
    if (!s_demo_ride_seeded) {
        bicycle_runtime_reset_session();
        bicycle_runtime_set_recording(true);
        bicycle_runtime_seed_session(12300.0, 1522000ull);
        bicycle_runtime_update_env(326.0f, true, 2.4f, 0.0f);
        bicycle_runtime_update_sensors(148, true, 84, true, 220, true);
        (void)myvendor_devctl_autopause_set(false);
        s_demo_ride_seeded = true;
    }
    if (speed_kph < 0.0f) {
        speed_kph = 0.0f;
    } else if (speed_kph > 60.0f) {
        speed_kph = 60.0f;
    }
    s_demo_speed_kph = speed_kph;
    drt = (bicycle_runtime_t *)(uintptr_t)bicycle_runtime_get();
    if (drt != NULL) {
        drt->speed_kph = speed_kph;
        drt->has_altitude = true;
        drt->altitude_m = 326.0f;
        drt->grade_pct = 2.4f;
    }
    /* 传感器桩每 10 ms 会把值改回 128/84；这里每次调用都重放取证值，
     * 保证紧接着的 `helm_refresh_numbers()` 读到的就是 148。 */
    bicycle_runtime_update_sensors(148, true, 84, true, 220, true);
    helm_refresh_numbers();
    printf("helm: demo ride speed=%.1f\n", (double)speed_kph);
}

void helm_shell_demo_pause(bool on)
{
    if (!s_sh.attached) {
        return;
    }
    helm_demo_runtime_apply();
    s_sh.paused = on;
    /* 本包只验页面里的"数字退灰"；暂停条是 S4 的覆盖层，取证时先收起。 */
    helm_show(s_sh.pause_dock, false);
    helm_refresh_numbers();
    printf("helm: demo pause=%d\n", on ? 1 : 0);
}

/* ── 演示：骑行两页的几何/墨迹 dump（布局断言脚本读 verify.log）──────────
 * 坐标与 S2 的 [ring] dump 同一口径：**屏幕坐标**（页面根从 y=24 开始，
 * 脚本减 24 得页面坐标）。刻度是页面根坐标的点集（不经过对象 bbox）。 */
static void helm_ride_dump_geo(const char * tag, const char * name,
                               lv_obj_t * obj)
{
    lv_area_t c;

    if (obj == NULL) {
        printf("[%s] geo %s=null\n", tag, name);
        return;
    }
    lv_obj_get_coords(obj, &c);
    printf("[%s] geo %s=%d,%d,%d,%d\n", tag, name, (int)c.x1, (int)c.y1,
           (int)c.x2, (int)c.y2);
}

static void helm_ride_dump_ink(const char * tag, const char * name,
                               lv_obj_t * obj)
{
    const lv_font_t * font;
    const char * txt;
    lv_point_t sz;

    if (obj == NULL) {
        printf("[%s] ink %s=null\n", tag, name);
        return;
    }
    font = lv_obj_get_style_text_font(obj, 0);
    txt = lv_label_get_text(obj);
    if (font == NULL || txt == NULL) {
        printf("[%s] ink %s=0x0\n", tag, name);
        return;
    }
    lv_text_get_size(&sz, txt, font, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
    printf("[%s] ink %s=%dx%d\n", tag, name, (int)sz.x, (int)sz.y);
}

static void helm_ride_dump_text(const char * tag, const char * name,
                                lv_obj_t * obj)
{
    if (obj == NULL) {
        printf("[%s] text %s=null\n", tag, name);
        return;
    }
    printf("[%s] text %s=%s\n", tag, name, lv_label_get_text(obj));
}

static void helm_ride_dump_color(const char * tag, const char * name,
                                 lv_obj_t * obj)
{
    lv_color_t c;

    if (obj == NULL) {
        printf("[%s] color %s=null\n", tag, name);
        return;
    }
    c = lv_obj_get_style_text_color(obj, 0);
    printf("[%s] color %s=%02X%02X%02X\n", tag, name,
           (unsigned)c.red, (unsigned)c.green, (unsigned)c.blue);
}

