/**
 * @brief 页面总数（用户 2026-09-26 的清单；R1-S3a 骑行轮转缩到 3 页）。
 * @details 待机 3 页：主页面 / 骑行页 / 数据页。
 *          骑行 3 页：表盘 / 数字方阵 / 地图页。
 * @note **待机没有单独的"地图页"**：用户原话"主页面就是地图页，只是下半部分
 *       组件不一样了" —— 主页面（STANDBY）本来就是地图 + 信息卡，`map_on` 里
 *       STANDBY 与 MAP 都会让地图显示，所以待机不必再列一页地图。
 * @note **导航也不再插转向页**：导航时同样是这 3 页（转向信息走地图上的
 *       通栏横幅/路牌，不需要单独一页）。TURN / CLIMB pane 仍建着、只是不在
 *       轮转表里（CLIMB 由 S3a 移出，页面代码保留到 S5 再摘）。
 */
static uint8_t helm_page_count(void)
{
    return helm_in_session() ? HELM_RIDE_PAGE_N : 3u;
}

static helm_page_id_t helm_page_at(uint8_t idx)
{
    /* 演示页面锁：忽略正常轮转表，恒返回强制页。 */
    if (s_demo_page != (helm_page_id_t)0xff) {
        return s_demo_page;
    }

    if (!helm_in_session()) {
        /* R1-S2：环形主页（HELM_PAGE_RING）取代待机页成为 home。待机 pane 与
         * 旧数据页仍保留（演示/骑行路径可达），S3/S5 再摘。 */
        static const helm_page_id_t idle[] = {
            HELM_PAGE_RING, HELM_PAGE_DATA, HELM_PAGE_DATA_ALL
        };
        return idle[idx % (uint8_t)(sizeof(idle) / sizeof(idle[0]))];
    }

    {
        /* R1-S3a：骑行轮转 = 表盘 / 数字方阵 / 地图；CLIMB 不再出现。 */
        static const helm_page_id_t r[] = {
            HELM_PAGE_DATA, HELM_PAGE_DATA_ALL, HELM_PAGE_MAP
        };
        return r[idx % (uint8_t)(sizeof(r) / sizeof(r[0]))];
    }
}

