static void helm_map_card_nav_text(char * big, size_t n, const char ** act)
{
    char ico[8], dist[40], sub[32];
    double td, rm;

    if (s_banner_demo_mode != 0) {
        static const char *const d_big[8] = {"", "12.3 km", "228 m", "120 m",
                                             "0 m", "300 m", "300 m", "--"};
        static const char *const d_act[8] = {"", "直行", "左转", "偏航",
                                             "已到达", "右转", "掉头", "重新规划"};
        lv_snprintf(big, n, "%s", d_big[s_banner_demo_mode & 7]);
        *act = d_act[s_banner_demo_mode & 7];
        return;
    }
    if (!map_page_nav_turn_info(s_sh.map, ico, sizeof(ico), dist, sizeof(dist), sub, sizeof(sub))) {
        lv_snprintf(big, n, "--");
        *act = "导航中";
        return;
    }
    td = map_page_nav_turn_dist_m(s_sh.map);
    rm = map_page_nav_remain_m(s_sh.map);
    if (td >= 1000.0) {
        lv_snprintf(big, n, "%.1f km", td / 1000.0);
    } else if (td >= 0.0) {
        lv_snprintf(big, n, "%.0f m", td);
    } else if (rm >= 1000.0) {
        lv_snprintf(big, n, "%.1f km", rm / 1000.0);
    } else if (rm >= 0.0) {
        lv_snprintf(big, n, "%.0f m", rm);
    } else {
        lv_snprintf(big, n, "--");
    }
    *act = helm_map_card_turn_act(ico);
}
