/**
 * @brief 骑行页 3：全屏地图的底部浮层卡（R1-S3b）。
 *
 * @details 几何与模拟器 scene_helm.c 的 `ride_build_map()` 一致（页面根坐标，
 *          屏幕 y = 页面 y + 24）：
 *            卡片 (12,212,216,76)，纸底 95%、1px 发丝边、圆角 10；
 *            左缘 3px 骑行绿竖条 (0,12,3,52)；
 *            速度 36px @ (14,4)，km/h 12px @ (14,44)，已骑 12px @ (14,58)；
 *            分隔线卡内 x=99、y=8..66；
 *            右块大字 22px @ (108,4) + 小字 12px @ (108,32)（两态共用）。
 *          数值全部来自 `bicycle_runtime` / `map_page_nav_*`，见
 *          `helm_map_card_tick()`；这里只搭骨架。
 */
static void helm_build_map_card(lv_obj_t * root)
{
    lv_obj_t * card;

    card = helm_dial_box(root, HELM_MAP_CARD_X, HELM_MAP_CARD_Y,
                         HELM_MAP_CARD_W, HELM_MAP_CARD_H,
                         HELM_COLOR_PAPER, (lv_opa_t)242, HELM_RADIUS);
    lv_obj_set_style_border_width(card, 1, 0);
    lv_obj_set_style_border_color(card, helm_color(HELM_COLOR_HAIR), 0);
    lv_obj_set_style_border_opa(card, LV_OPA_COVER, 0);
    lv_obj_add_flag(card, LV_OBJ_FLAG_HIDDEN);
    s_sh.map_card = card;

    /* 骑行身份绿竖条：卡内 (0,12,3,52)。 */
    s_sh.map_card_bar = helm_dial_box(card, 0, 12, 3, 52,
                                      HELM_COLOR_OK, LV_OPA_COVER, 1);
    /* 左右块之间的发丝分隔线：卡内 x=99、y=8..66。 */
    s_sh.map_card_sep = helm_dial_box(card, HELM_MAP_CARD_SPLIT, 8, 1, 58,
                                      HELM_COLOR_HAIR, LV_OPA_COVER, 0);

    /* 左块：时速 36px（TTF 36；工厂固件回退 32px 点阵）。定宽 + CLIP，
     * 保证对象盒收在分隔线之前（S2 踩过"单位跟着数字右移压线"）。 */
    s_sh.map_card_speed = helm_lab(card, helm_font_sys(36, s_sh.font_quad),
                                   HELM_COLOR_INK, "--");
    lv_obj_set_pos(s_sh.map_card_speed, 14, 4);
    lv_obj_set_size(s_sh.map_card_speed, HELM_MAP_CARD_LEFT_W, 40);
    lv_label_set_long_mode(s_sh.map_card_speed, LV_LABEL_LONG_MODE_CLIP);

    s_sh.map_card_unit = helm_lab(card, s_sh.font_lab, HELM_COLOR_MUTE, "km/h");
    lv_obj_set_pos(s_sh.map_card_unit, 14, 44);

    s_sh.map_card_dist = helm_lab(card, s_sh.font_lab, HELM_COLOR_MUTE,
                                  "已骑 0.0 km");
    lv_obj_set_pos(s_sh.map_card_dist, 14, 58);
    lv_obj_set_width(s_sh.map_card_dist, HELM_MAP_CARD_LEFT_W);
    lv_label_set_long_mode(s_sh.map_card_dist, LV_LABEL_LONG_MODE_CLIP);

    /* 右块：两态共用同一对 label（导航=距离+动作；未导航=时长+本次骑行）。 */
    s_sh.map_card_rv = helm_lab(card, s_sh.font_val, HELM_COLOR_INK, "--");
    lv_obj_set_pos(s_sh.map_card_rv, 108, 4);
    s_sh.map_card_rsub = helm_lab(card, s_sh.font_lab, HELM_COLOR_MUTE,
                                  "本次骑行");
    lv_obj_set_pos(s_sh.map_card_rsub, 108, 32);
}

