static const char * helm_map_card_turn_act(const char * ico)
{
    if (ico == NULL) {
        return "导航中";
    }
    if (strcmp(ico, "←") == 0) {
        return "左转";
    }
    if (strcmp(ico, "→") == 0) {
        return "右转";
    }
    if (strcmp(ico, "U") == 0) {
        return "掉头";
    }
    if (strcmp(ico, "●") == 0) {
        return "已到达";
    }
    return "直行";
}

/**
 * @brief 右块导航态文案：大字=到下一转向的距离，小字=动作。
 *
 * @details 真实数据全部复用地图页 API：`map_page_nav_turn_info()` 给箭头 +
 *          动作（与横幅同源），`map_page_nav_turn_dist_m()` /
 *          `map_page_nav_remain_m()` 给紧凑距离（≥1 km 一位小数，其余整米）。
 *          演示态（`s_banner_demo_mode`）沿用横幅那套示意值，只用于模拟器
 *          出图；板端正常路径不会置这个变量。
 */
static void helm_map_card_nav_text(char * big, size_t n, const char ** act)
{
    char ico[8];
    char dist[40];
    char sub[32];
    double td;
    double rm;

    if (s_banner_demo_mode != 0) {
        static const char *const d_big[8] = {
            "", "12.3 km", "228 m", "120 m", "0 m", "300 m", "300 m", "--"
        };
        static const char *const d_act[8] = {
            "", "直行", "左转", "偏航", "已到达", "右转", "掉头", "重新规划"
        };
        const int m = s_banner_demo_mode & 7;

        lv_snprintf(big, n, "%s", d_big[m]);
        *act = d_act[m];
        return;
    }

    if (!map_page_nav_turn_info(s_sh.map, ico, sizeof(ico), dist, sizeof(dist),
                                sub, sizeof(sub))) {
        lv_snprintf(big, n, "--");
        *act = "导航中";
        return;
    }

    td = map_page_nav_turn_dist_m(s_sh.map);
    rm = map_page_nav_remain_m(s_sh.map);
    if (td >= 1000.0) {
        lv_snprintf(big, n, "%.1f km", td / 1000.0);
    } else if (td >= 0.0) {
        lv_snprintf(big, n, "%.0f m", td);
    } else if (rm >= 1000.0) {
        lv_snprintf(big, n, "%.1f km", rm / 1000.0);
    } else if (rm >= 0.0) {
        lv_snprintf(big, n, "%.0f m", rm);
    } else {
        lv_snprintf(big, n, "--");
    }
    *act = helm_map_card_turn_act(ico);
}

/** @brief 全屏地图浮层卡刷值（500 ms UI 节拍）。 */
static void helm_map_card_tick(const bicycle_runtime_t * rt)
{
    const bool paused = s_sh.paused;
    const uint32_t ink = paused ? HELM_COLOR_TRACK : HELM_COLOR_INK;
    bool nav;
    char buf[32];
    char line[48];

    if (s_sh.map_card_speed == NULL) {
        return;
    }

    /* 36px 系统字可能晚于建页就绪（与方阵 30px 同一套晚绑定处理）；
     * 没 TTF 的工厂固件保持建页时的 32px 点阵回退。 */
    {
        const lv_font_t * f36 = helm_font_sys(36, s_sh.font_quad);

        if (f36 != NULL &&
            lv_obj_get_style_text_font(s_sh.map_card_speed, 0) != f36) {
            lv_obj_set_style_text_font(s_sh.map_card_speed, f36, 0);
            lv_obj_set_style_text_letter_space(s_sh.map_card_speed, 0, 0);
        }
    }

    helm_fmt_speed(buf, sizeof(buf), rt ? rt->speed_kph : 0.0f);
    helm_label_set(s_sh.map_card_speed, buf);
    helm_set_text_hex(s_sh.map_card_speed, ink);

    helm_label_set(s_sh.map_card_unit, "km/h");
    helm_set_text_hex(s_sh.map_card_unit, HELM_COLOR_MUTE);

    helm_fmt_km(buf, sizeof(buf),
                rt ? (float)(rt->session_distance_m / 1000.0) : 0.0f);
    lv_snprintf(line, sizeof(line), "已骑 %s km", buf);
    helm_label_set(s_sh.map_card_dist, line);
    helm_set_text_hex(s_sh.map_card_dist, HELM_COLOR_MUTE);

    nav = (s_banner_demo_mode != 0) || map_page_nav_active(s_sh.map);
    if (nav) {
        const char * act = "导航中";
        char nb[24];

        helm_map_card_nav_text(nb, sizeof(nb), &act);
        helm_label_set(s_sh.map_card_rv, nb);
        /* 导航距离不是骑行计量值，暂停也不退灰（"速度/时长退灰"只指左块
         * 与未导航态的时长）。 */
        helm_set_text_hex(s_sh.map_card_rv, HELM_COLOR_INK);
        helm_label_set(s_sh.map_card_rsub, act);
        helm_set_text_hex(s_sh.map_card_rsub, HELM_COLOR_MUTE);
    } else {
        helm_fmt_time(buf, sizeof(buf), rt ? rt->session_elapsed_ms : 0ull);
        helm_label_set(s_sh.map_card_rv, buf);
        helm_set_text_hex(s_sh.map_card_rv, ink);
        helm_label_set(s_sh.map_card_rsub, "本次骑行");
        helm_set_text_hex(s_sh.map_card_rsub, HELM_COLOR_MUTE);
    }
}

